import React, {
  useEffect,
  useRef,
  useState,
} from 'react';

import { toast } from 'react-toastify';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiImage,
  FiHome,
  FiCheckCircle,
  FiGlobe,
} from 'react-icons/fi';

import api, {
  getApiErrorMessage,
} from '../../services/api';

import {
  getImageUrl,
} from '../../utils/helpers';

import {
  useLanguage,
} from '../../contexts/LanguageContext';

import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';


const DEFAULT_IMG = '/default-avatar.png';


const initialForm = {
  name_en: '',
  name_km: '',
  acronym: '',
  tag_en: '',
  tag_km: '',
  description_en: '',
  description_km: '',
  features_en: '',
  features_km: '',
  is_active: true,
  order: 0,
};


const AdminSchools = () => {

  const {
    language,
  } = useLanguage();


  const [schools, setSchools] = useState([]);

  const [loading, setLoading] = useState(true);

  const [modalOpen, setModalOpen] = useState(false);

  const [editingSchool, setEditingSchool] = useState(null);

  const [formData, setFormData] = useState(initialForm);

  const [imageFile, setImageFile] = useState(null);

  const [submitting, setSubmitting] = useState(false);


  const fileRef = useRef(null);


  const isKhmer =
    language === 'km' ||
    language === 'kh';


  const text = {

    pageTitle: isKhmer
      ? 'គ្រប់គ្រងសាលា'
      : 'Schools Management',

    pageSubtitle: isKhmer
      ? 'គ្រប់គ្រងព័ត៌មានសាលា និងមាតិកាភាសាខ្មែរ និងអង់គ្លេស'
      : 'Manage school information and bilingual content',

    addSchool: isKhmer
      ? 'បន្ថែមសាលា'
      : 'Add School',

    createSchool: isKhmer
      ? 'បង្កើតសាលា'
      : 'Create School',

    editSchool: isKhmer
      ? 'កែប្រែសាលា'
      : 'Edit School',

    updateSchool: isKhmer
      ? 'រក្សាទុកការកែប្រែ'
      : 'Update School',

    deleteSchool: isKhmer
      ? 'លុបសាលា'
      : 'Delete School',

    image: isKhmer
      ? 'រូបភាព'
      : 'Image',

    acronym: isKhmer
      ? 'អក្សរកាត់'
      : 'Acronym',

    schoolName: isKhmer
      ? 'ឈ្មោះសាលា'
      : 'School Name',

    tag: isKhmer
      ? 'ស្លាក'
      : 'Tag',

    displayOrder: isKhmer
      ? 'លំដាប់បង្ហាញ'
      : 'Display Order',

    status: isKhmer
      ? 'ស្ថានភាព'
      : 'Status',

    actions: isKhmer
      ? 'សកម្មភាព'
      : 'Actions',

    active: isKhmer
      ? 'សកម្ម'
      : 'Active',

    inactive: isKhmer
      ? 'អសកម្ម'
      : 'Inactive',

    englishSection: isKhmer
      ? 'ព័ត៌មានជាភាសាអង់គ្លេស'
      : 'English Information',

    khmerSection: isKhmer
      ? 'ព័ត៌មានជាភាសាខ្មែរ'
      : 'Khmer Information',

    generalInformation: isKhmer
      ? 'ព័ត៌មានទូទៅ'
      : 'General Information',

    englishSchoolName: isKhmer
      ? 'ឈ្មោះសាលាជាភាសាអង់គ្លេស'
      : 'School Name',

    englishTag: isKhmer
      ? 'ស្លាកជាភាសាអង់គ្លេស'
      : 'Tag',

    englishDescription: isKhmer
      ? 'ការពិពណ៌នាជាភាសាអង់គ្លេស'
      : 'Description',

    englishFeatures: isKhmer
      ? 'លក្ខណៈពិសេសជាភាសាអង់គ្លេស'
      : 'Features',

    khmerSchoolName: isKhmer
      ? 'ឈ្មោះសាលាជាភាសាខ្មែរ'
      : 'School Name in Khmer',

    khmerTag: isKhmer
      ? 'ស្លាកជាភាសាខ្មែរ'
      : 'Tag in Khmer',

    khmerDescription: isKhmer
      ? 'ការពិពណ៌នាជាភាសាខ្មែរ'
      : 'Description in Khmer',

    khmerFeatures: isKhmer
      ? 'លក្ខណៈពិសេសជាភាសាខ្មែរ'
      : 'Features in Khmer',

    englishNamePlaceholder: isKhmer
      ? 'បញ្ចូលឈ្មោះសាលាជាភាសាអង់គ្លេស'
      : 'Enter school name',

    englishTagPlaceholder: isKhmer
      ? 'បញ្ចូលស្លាកជាភាសាអង់គ្លេស'
      : 'Example: Technology School',

    englishDescriptionPlaceholder: isKhmer
      ? 'បញ្ចូលការពិពណ៌នាជាភាសាអង់គ្លេស'
      : 'Enter school description',

    englishFeaturesPlaceholder: isKhmer
      ? 'បញ្ចូលលក្ខណៈពិសេសជាភាសាអង់គ្លេស'
      : 'Enter school features',

    khmerNamePlaceholder: isKhmer
      ? 'បញ្ចូលឈ្មោះសាលាជាភាសាខ្មែរ'
      : 'Enter school name in Khmer',

    khmerTagPlaceholder: isKhmer
      ? 'ឧទាហរណ៍៖ សាលាបច្ចេកវិទ្យា'
      : 'Example: សាលាបច្ចេកវិទ្យា',

    khmerDescriptionPlaceholder: isKhmer
      ? 'បញ្ចូលការពិពណ៌នាជាភាសាខ្មែរ'
      : 'Enter school description in Khmer',

    khmerFeaturesPlaceholder: isKhmer
      ? 'បញ្ចូលលក្ខណៈពិសេសជាភាសាខ្មែរ'
      : 'Enter school features in Khmer',

    schoolImage: isKhmer
      ? 'រូបភាពសាលា'
      : 'School Image',

    uploadImage: isKhmer
      ? 'ចុចដើម្បីជ្រើសរើសរូបភាព'
      : 'Click to upload image',

    chooseAnotherImage: isKhmer
      ? 'ចុចដើម្បីជ្រើសរើសរូបភាពផ្សេង'
      : 'Click to choose another image',

    keepCurrentImage: isKhmer
      ? 'រក្សារូបភាពបច្ចុប្បន្ន'
      : 'Keep current image',

    imageHelp: isKhmer
      ? 'អនុញ្ញាត JPG, JPEG, PNG, WEBP — ទំហំអតិបរមា 5 MB'
      : 'JPG, JPEG, PNG, WEBP — Max 5 MB',

    schoolStatus: isKhmer
      ? 'ស្ថានភាពសាលា'
      : 'School Status',

    showOnWebsite: isKhmer
      ? 'បើកដើម្បីបង្ហាញសាលានេះនៅលើគេហទំព័រ'
      : 'Enable to show this school on the website',

    cancel: isKhmer
      ? 'បោះបង់'
      : 'Cancel',

    saving: isKhmer
      ? 'កំពុងរក្សាទុក...'
      : 'Saving...',

    loadingFailed: isKhmer
      ? 'មិនអាចទាញយកទិន្នន័យសាលាបានទេ។'
      : 'Failed to load schools.',

    createSuccess: isKhmer
      ? 'បានបង្កើតសាលាដោយជោគជ័យ។'
      : 'School created successfully.',

    updateSuccess: isKhmer
      ? 'បានកែប្រែសាលាដោយជោគជ័យ។'
      : 'School updated successfully.',

    operationFailed: isKhmer
      ? 'ប្រតិបត្តិការបរាជ័យ។ សូមព្យាយាមម្ដងទៀត។'
      : 'Operation failed. Please try again.',

    deleteSuccess: isKhmer
      ? 'បានលុបសាលាដោយជោគជ័យ។'
      : 'School deleted successfully.',

    deleteFailed: isKhmer
      ? 'មិនអាចលុបសាលាបានទេ។'
      : 'Failed to delete school.',

    deleteConfirm: isKhmer
      ? 'តើអ្នកពិតជាចង់លុបសាលានេះមែនទេ?'
      : 'Are you sure you want to delete this school?',

    invalidImage: isKhmer
      ? 'ប្រភេទរូបភាពមិនត្រឹមត្រូវ។ អនុញ្ញាតតែ JPG, JPEG, PNG និង WEBP។'
      : 'Invalid image type. Allowed: JPG, JPEG, PNG and WEBP.',

    imageTooLarge: isKhmer
      ? 'រូបភាពត្រូវមានទំហំ 5 MB ឬតូចជាងនេះ។'
      : 'Image must be 5 MB or smaller.',

    englishNameRequired: isKhmer
      ? 'សូមបញ្ចូលឈ្មោះសាលាជាភាសាអង់គ្លេស។'
      : 'English school name is required.',

    khmerNameRequired: isKhmer
      ? 'សូមបញ្ចូលឈ្មោះសាលាជាភាសាខ្មែរ។'
      : 'Khmer school name is required.',

    currentImageAlt: isKhmer
      ? 'រូបភាពសាលាបច្ចុប្បន្ន'
      : 'Current school image',

    schoolImageAlt: isKhmer
      ? 'រូបភាពសាលា'
      : 'School image',

  };


  const getSchoolName = (school) => {

    if (!school) {
      return '-';
    }

    if (isKhmer) {
      return (
        school.name_km ||
        school.name_en ||
        '-'
      );
    }

    return (
      school.name_en ||
      school.name_km ||
      '-'
    );

  };


  const getSchoolTag = (school) => {

    if (!school) {
      return '-';
    }

    if (isKhmer) {
      return (
        school.tag_km ||
        school.tag_en ||
        '-'
      );
    }

    return (
      school.tag_en ||
      school.tag_km ||
      '-'
    );

  };


  useEffect(() => {

    fetchSchools();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);


  const fetchSchools = async () => {

    try {

      setLoading(true);

      const response = await api.get(
        '/api/schools/all'
      );

      setSchools(
        Array.isArray(response.data)
          ? response.data
          : []
      );

    } catch (error) {

      console.error(
        'Fetch schools error:',
        error
      );

      toast.error(
        getApiErrorMessage(
          error,
          text.loadingFailed
        )
      );

    } finally {

      setLoading(false);

    }

  };


  const resetForm = () => {

    setEditingSchool(null);

    setFormData({
      ...initialForm,
    });

    setImageFile(null);

    setSubmitting(false);

    if (fileRef.current) {
      fileRef.current.value = '';
    }

  };


  const openCreateModal = () => {

    resetForm();

    setModalOpen(true);

  };


  const closeModal = () => {

    if (submitting) {
      return;
    }

    setModalOpen(false);

    resetForm();

  };


  const handleInputChange = (e) => {

    const {
      name,
      value,
      type,
      checked,
    } = e.target;

    setFormData((prev) => ({
      ...prev,
      [name]:
        type === 'checkbox'
          ? checked
          : value,
    }));

  };


  const handleImageChange = (e) => {

    const file = e.target.files?.[0];

    if (!file) {

      setImageFile(null);

      return;

    }


    const allowedTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'image/webp',
    ];


    if (!allowedTypes.includes(file.type)) {

      toast.error(
        text.invalidImage
      );

      e.target.value = '';

      setImageFile(null);

      return;

    }


    if (file.size > 5 * 1024 * 1024) {

      toast.error(
        text.imageTooLarge
      );

      e.target.value = '';

      setImageFile(null);

      return;

    }


    setImageFile(file);

  };


  const handleEdit = (school) => {

    setEditingSchool(school);

    setFormData({

      name_en:
        school.name_en || '',

      name_km:
        school.name_km || '',

      acronym:
        school.acronym || '',

      tag_en:
        school.tag_en || '',

      tag_km:
        school.tag_km || '',

      description_en:
        school.description_en || '',

      description_km:
        school.description_km || '',

      features_en:
        school.features_en || '',

      features_km:
        school.features_km || '',

      is_active:
        school.is_active ?? true,

      order:
        school.order ?? 0,

    });


    setImageFile(null);


    if (fileRef.current) {
      fileRef.current.value = '';
    }


    setModalOpen(true);

  };


  const handleSubmit = async (e) => {

    e.preventDefault();


    if (!formData.name_en.trim()) {

      toast.error(
        text.englishNameRequired
      );

      return;

    }


    if (!formData.name_km.trim()) {

      toast.error(
        text.khmerNameRequired
      );

      return;

    }


    try {

      setSubmitting(true);


      const fd = new FormData();


      fd.append(
        'name_en',
        formData.name_en.trim()
      );

      fd.append(
        'tag_en',
        formData.tag_en.trim()
      );

      fd.append(
        'description_en',
        formData.description_en.trim()
      );

      fd.append(
        'features_en',
        formData.features_en.trim()
      );


      fd.append(
        'name_km',
        formData.name_km.trim()
      );

      fd.append(
        'tag_km',
        formData.tag_km.trim()
      );

      fd.append(
        'description_km',
        formData.description_km.trim()
      );

      fd.append(
        'features_km',
        formData.features_km.trim()
      );


      fd.append(
        'acronym',
        formData.acronym.trim()
      );

      fd.append(
        'is_active',
        String(formData.is_active)
      );

      fd.append(
        'order',
        String(
          Number(formData.order) || 0
        )
      );


      if (imageFile) {

        fd.append(
          'image',
          imageFile
        );

      }


      if (editingSchool) {

        await api.put(
          '/api/schools/' + editingSchool.id,
          fd
        );

        toast.success(
          text.updateSuccess
        );

      } else {

        await api.post(
          '/api/schools/',
          fd
        );

        toast.success(
          text.createSuccess
        );

      }


      setModalOpen(false);

      resetForm();

      await fetchSchools();

    } catch (error) {

      console.error(
        'School submit error:',
        error
      );

      toast.error(
        getApiErrorMessage(
          error,
          text.operationFailed
        )
      );

    } finally {

      setSubmitting(false);

    }

  };


  const handleDelete = async (id) => {

    const confirmDelete =
      window.confirm(
        text.deleteConfirm
      );


    if (!confirmDelete) {
      return;
    }


    try {

      await api.delete(
        '/api/schools/' + id
      );

      toast.success(
        text.deleteSuccess
      );

      await fetchSchools();

    } catch (error) {

      console.error(
        'Delete school error:',
        error
      );

      toast.error(
        getApiErrorMessage(
          error,
          text.deleteFailed
        )
      );

    }

  };


  const columns = [

    {
      key: 'image',

      label: text.image,

      render: (value) => (

        <div
          className="
            w-20
            h-14
            rounded-xl
            overflow-hidden
            border
            border-blue-200
            bg-blue-50
            shadow-sm
          "
        >

          <img
            src={
              getImageUrl(
                value,
                DEFAULT_IMG
              )
            }
            alt={
              text.schoolImageAlt
            }
            className="
              w-full
              h-full
              object-cover
            "
            onError={(e) => {
              e.currentTarget.src =
                DEFAULT_IMG;
            }}
          />

        </div>

      ),
    },


    {
      key: 'acronym',

      label: text.acronym,

      render: (value) => (

        <span
          className="
            inline-flex
            items-center
            justify-center
            min-w-[52px]
            px-3
            py-1.5
            rounded-lg
            bg-blue-50
            text-blue-900
            border
            border-blue-200
            text-xs
            font-bold
          "
        >
          {value || '-'}
        </span>

      ),
    },


    {
      key: 'name_en',

      label: text.schoolName,

      render: (value, row) => (

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-9
              h-9
              flex
              items-center
              justify-center
              rounded-lg
              bg-blue-50
              text-blue-900
              flex-shrink-0
            "
          >

            <FiHome
              size={17}
            />

          </div>


          <div>

            <p
              className="
                font-semibold
                text-blue-900
              "
            >
              {getSchoolName(row)}
            </p>


            {
              row.name_en &&
              row.name_km && (

                <p
                  className="
                    text-xs
                    text-blue-300
                    mt-0.5
                  "
                >
                  {
                    isKhmer
                      ? row.name_en
                      : row.name_km
                  }
                </p>

              )
            }

          </div>

        </div>

      ),
    },


    {
      key: 'tag_en',

      label: text.tag,

      render: (value, row) => (

        <span
          className="
            inline-flex
            px-3
            py-1.5
            rounded-full
            bg-blue-50
            text-blue-500
            text-xs
            font-medium
          "
        >
          {getSchoolTag(row)}
        </span>

      ),
    },


    {
      key: 'order',

      label: text.displayOrder,

      render: (value) => (

        <span
          className="
            inline-flex
            items-center
            justify-center
            w-8
            h-8
            rounded-lg
            bg-blue-50
            text-blue-900
            font-semibold
            text-xs
          "
        >
          {value ?? 0}
        </span>

      ),
    },


    {
      key: 'is_active',

      label: text.status,

      render: (value) => (

        <span
          className={
            value
              ? 'inline-flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-semibold border bg-green-50 text-green-700 border-green-200'
              : 'inline-flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-semibold border bg-red-50 text-red-600 border-red-200'
          }
        >

          <span
            className={
              value
                ? 'w-2 h-2 rounded-full bg-green-500'
                : 'w-2 h-2 rounded-full bg-red-500'
            }
          />

          {
            value
              ? text.active
              : text.inactive
          }

        </span>

      ),
    },


    {
      key: 'actions',

      label: text.actions,

      render: (value, row) => (

        <div
          className="
            flex
            items-center
            gap-2
          "
        >

          <button
            type="button"
            onClick={() =>
              handleEdit(row)
            }
            title={
              text.editSchool
            }
            className="
              w-9
              h-9
              flex
              items-center
              justify-center
              rounded-lg
              bg-blue-50
              text-blue-900
              hover:bg-blue-900
              hover:text-white
              transition-all
              duration-200
            "
          >

            <FiEdit2
              size={16}
            />

          </button>


          <button
            type="button"
            onClick={() =>
              handleDelete(row.id)
            }
            title={
              text.deleteSchool
            }
            className="
              w-9
              h-9
              flex
              items-center
              justify-center
              rounded-lg
              bg-red-50
              text-red-600
              hover:bg-red-600
              hover:text-white
              transition-all
              duration-200
            "
          >

            <FiTrash2
              size={16}
            />

          </button>

        </div>

      ),
    },

  ];


  return (

    <div
      className={
        isKhmer
          ? 'w-full font-khmer'
          : 'w-full font-english'
      }
    >

      <div
        className="
          flex
          flex-col
          sm:flex-row
          sm:items-center
          sm:justify-between
          gap-4
          mb-7
        "
      >

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-12
              h-12
              flex
              items-center
              justify-center
              rounded-xl
              bg-blue-900
              text-white
              shadow-sm
              flex-shrink-0
            "
          >

            <FiHome
              size={22}
            />

          </div>


          <div>

            <h1
              className="
                text-2xl
                sm:text-3xl
                font-bold
                text-blue-900
                leading-tight
              "
            >
              {text.pageTitle}
            </h1>

            <p
              className="
                text-sm
                text-blue-400
                mt-1
              "
            >
              {text.pageSubtitle}
            </p>

          </div>

        </div>


        <button
          type="button"
          onClick={
            openCreateModal
          }
          className="
            inline-flex
            items-center
            justify-center
            gap-2
            h-11
            px-5
            bg-red-600
            hover:bg-red-700
            text-white
            rounded-xl
            text-sm
            font-semibold
            shadow-sm
            hover:shadow-md
            transition-all
            duration-200
          "
        >

          <FiPlus
            size={18}
          />

          {text.addSchool}

        </button>

      </div>


      <AdminCard
        className="
          overflow-hidden
          bg-white
          border
          border-blue-200
          rounded-2xl
          shadow-sm
        "
      >

        <AdminTable
          columns={columns}
          data={schools}
          loading={loading}
        />

      </AdminCard>


      <AdminModal
        isOpen={
          modalOpen
        }
        onClose={
          closeModal
        }
        title={
          editingSchool
            ? text.editSchool
            : text.createSchool
        }
      >

        <form
          onSubmit={
            handleSubmit
          }
        >

          <div
            className="
              space-y-6
            "
          >

            <div
              className="
                border
                border-blue-200
                rounded-2xl
                overflow-hidden
              "
            >

              <div
                className="
                  flex
                  items-center
                  gap-2
                  px-4
                  py-3
                  bg-blue-50
                  border-b
                  border-blue-200
                "
              >

                <FiGlobe
                  className="
                    text-blue-900
                  "
                />

                <h3
                  className="
                    font-semibold
                    text-blue-900
                  "
                >
                  {text.englishSection}
                </h3>

              </div>


              <div
                className="
                  p-4
                  space-y-4
                  font-english
                "
              >

                <div>

                  <label
                    className="
                      admin-label
                    "
                  >

                    {text.englishSchoolName}

                    <span
                      className="
                        text-red-600
                        ml-1
                      "
                    >
                      *
                    </span>

                  </label>


                  <input
                    type="text"
                    name="name_en"
                    value={
                      formData.name_en
                    }
                    onChange={
                      handleInputChange
                    }
                    className="
                      admin-input
                      font-english
                    "
                    placeholder={
                      text.englishNamePlaceholder
                    }
                    required
                  />

                </div>


                <div>

                  <label
                    className="
                      admin-label
                    "
                  >
                    {text.englishTag}
                  </label>

                  <input
                    type="text"
                    name="tag_en"
                    value={
                      formData.tag_en
                    }
                    onChange={
                      handleInputChange
                    }
                    className="
                      admin-input
                      font-english
                    "
                    placeholder={
                      text.englishTagPlaceholder
                    }
                  />

                </div>


                <div>

                  <label
                    className="
                      admin-label
                    "
                  >
                    {text.englishDescription}
                  </label>

                  <textarea
                    name="description_en"
                    value={
                      formData.description_en
                    }
                    onChange={
                      handleInputChange
                    }
                    rows="4"
                    className="
                      admin-input
                      resize-none
                      font-english
                    "
                    placeholder={
                      text.englishDescriptionPlaceholder
                    }
                  />

                </div>


                <div>

                  <label
                    className="
                      admin-label
                    "
                  >
                    {text.englishFeatures}
                  </label>

                  <textarea
                    name="features_en"
                    value={
                      formData.features_en
                    }
                    onChange={
                      handleInputChange
                    }
                    rows="3"
                    className="
                      admin-input
                      resize-none
                      font-english
                    "
                    placeholder={
                      text.englishFeaturesPlaceholder
                    }
                  />

                </div>

              </div>

            </div>


            <div
              className="
                border
                border-blue-200
                rounded-2xl
                overflow-hidden
              "
            >

              <div
                className="
                  flex
                  items-center
                  gap-2
                  px-4
                  py-3
                  bg-blue-50
                  border-b
                  border-blue-200
                "
              >

                <FiGlobe
                  className="
                    text-blue-900
                  "
                />

                <h3
                  className="
                    font-semibold
                    text-blue-900
                  "
                >
                  {text.khmerSection}
                </h3>

              </div>


              <div
                className="
                  p-4
                  space-y-4
                  font-khmer
                "
              >

                <div>

                  <label
                    className="
                      admin-label
                      font-khmer
                    "
                  >

                    {text.khmerSchoolName}

                    <span
                      className="
                        text-red-600
                        ml-1
                      "
                    >
                      *
                    </span>

                  </label>


                  <input
                    type="text"
                    name="name_km"
                    value={
                      formData.name_km
                    }
                    onChange={
                      handleInputChange
                    }
                    className="
                      admin-input
                      font-khmer
                    "
                    placeholder={
                      text.khmerNamePlaceholder
                    }
                    required
                  />

                </div>


                <div>

                  <label
                    className="
                      admin-label
                      font-khmer
                    "
                  >
                    {text.khmerTag}
                  </label>

                  <input
                    type="text"
                    name="tag_km"
                    value={
                      formData.tag_km
                    }
                    onChange={
                      handleInputChange
                    }
                    className="
                      admin-input
                      font-khmer
                    "
                    placeholder={
                      text.khmerTagPlaceholder
                    }
                  />

                </div>


                <div>

                  <label
                    className="
                      admin-label
                      font-khmer
                    "
                  >
                    {text.khmerDescription}
                  </label>

                  <textarea
                    name="description_km"
                    value={
                      formData.description_km
                    }
                    onChange={
                      handleInputChange
                    }
                    rows="4"
                    className="
                      admin-input
                      resize-none
                      font-khmer
                    "
                    placeholder={
                      text.khmerDescriptionPlaceholder
                    }
                  />

                </div>


                <div>

                  <label
                    className="
                      admin-label
                      font-khmer
                    "
                  >
                    {text.khmerFeatures}
                  </label>

                  <textarea
                    name="features_km"
                    value={
                      formData.features_km
                    }
                    onChange={
                      handleInputChange
                    }
                    rows="3"
                    className="
                      admin-input
                      resize-none
                      font-khmer
                    "
                    placeholder={
                      text.khmerFeaturesPlaceholder
                    }
                  />

                </div>

              </div>

            </div>


            <div
              className="
                border
                border-blue-200
                rounded-2xl
                overflow-hidden
              "
            >

              <div
                className="
                  px-4
                  py-3
                  bg-blue-50
                  border-b
                  border-blue-200
                "
              >

                <h3
                  className="
                    font-semibold
                    text-blue-900
                  "
                >
                  {text.generalInformation}
                </h3>

              </div>


              <div
                className="
                  p-4
                  space-y-5
                "
              >

                <div
                  className="
                    grid
                    grid-cols-1
                    md:grid-cols-2
                    gap-4
                  "
                >

                  <div>

                    <label
                      className="
                        admin-label
                      "
                    >
                      {text.acronym}
                    </label>

                    <input
                      type="text"
                      name="acronym"
                      value={
                        formData.acronym
                      }
                      onChange={
                        handleInputChange
                      }
                      className="
                        admin-input
                      "
                      placeholder="SC"
                    />

                  </div>


                  <div>

                    <label
                      className="
                        admin-label
                      "
                    >
                      {text.displayOrder}
                    </label>

                    <input
                      type="number"
                      name="order"
                      min="0"
                      value={
                        formData.order
                      }
                      onChange={
                        handleInputChange
                      }
                      className="
                        admin-input
                      "
                    />

                  </div>

                </div>


                <div>

                  <label
                    className="
                      admin-label
                    "
                  >
                    {text.schoolImage}
                  </label>


                  <div
                    onClick={() => {
                      if (fileRef.current) {
                        fileRef.current.click();
                      }
                    }}
                    className="
                      group
                      border-2
                      border-dashed
                      border-blue-200
                      hover:border-blue-900
                      bg-blue-50
                      rounded-2xl
                      px-5
                      py-7
                      text-center
                      cursor-pointer
                      transition-all
                      duration-200
                    "
                  >

                    <input
                      ref={
                        fileRef
                      }
                      type="file"
                      accept="image/jpeg,image/jpg,image/png,image/webp"
                      onChange={
                        handleImageChange
                      }
                      className="
                        hidden
                      "
                    />


                    {
                      imageFile ? (

                        <div>

                          <div
                            className="
                              w-14
                              h-14
                              mx-auto
                              mb-3
                              flex
                              items-center
                              justify-center
                              rounded-xl
                              bg-white
                              text-blue-900
                              border
                              border-blue-200
                            "
                          >

                            <FiImage
                              size={25}
                            />

                          </div>


                          <p
                            className="
                              text-sm
                              font-semibold
                              text-blue-900
                              break-all
                            "
                          >
                            {imageFile.name}
                          </p>


                          <p
                            className="
                              text-xs
                              text-blue-400
                              mt-1
                            "
                          >
                            {text.chooseAnotherImage}
                          </p>

                        </div>

                      ) : (

                        <div>

                          {
                            editingSchool &&
                            editingSchool.image ? (

                              <>

                                <img
                                  src={
                                    getImageUrl(
                                      editingSchool.image,
                                      DEFAULT_IMG
                                    )
                                  }
                                  alt={
                                    text.currentImageAlt
                                  }
                                  className="
                                    w-28
                                    h-20
                                    mx-auto
                                    mb-3
                                    object-cover
                                    rounded-xl
                                    border
                                    border-blue-200
                                  "
                                  onError={(e) => {
                                    e.currentTarget.src =
                                      DEFAULT_IMG;
                                  }}
                                />


                                <div
                                  className="
                                    inline-flex
                                    items-center
                                    gap-1.5
                                    px-3
                                    py-1.5
                                    rounded-full
                                    bg-white
                                    text-blue-900
                                    border
                                    border-blue-200
                                    text-xs
                                    font-medium
                                  "
                                >

                                  <FiCheckCircle />

                                  {text.keepCurrentImage}

                                </div>


                                <p
                                  className="
                                    text-xs
                                    text-blue-400
                                    mt-2
                                  "
                                >
                                  {text.chooseAnotherImage}
                                </p>

                              </>

                            ) : (

                              <>

                                <div
                                  className="
                                    w-14
                                    h-14
                                    mx-auto
                                    mb-3
                                    flex
                                    items-center
                                    justify-center
                                    rounded-xl
                                    bg-white
                                    border
                                    border-blue-200
                                    shadow-sm
                                    text-blue-400
                                    group-hover:text-blue-900
                                    group-hover:scale-105
                                    transition-all
                                  "
                                >

                                  <FiImage
                                    size={25}
                                  />

                                </div>


                                <p
                                  className="
                                    text-sm
                                    font-semibold
                                    text-blue-900
                                  "
                                >
                                  {text.uploadImage}
                                </p>


                                <p
                                  className="
                                    text-xs
                                    text-blue-400
                                    mt-1
                                  "
                                >
                                  {text.imageHelp}
                                </p>

                              </>

                            )
                          }

                        </div>

                      )
                    }

                  </div>

                </div>


                <div
                  className="
                    flex
                    items-center
                    justify-between
                    gap-4
                    px-4
                    py-3.5
                    rounded-xl
                    bg-blue-50
                    border
                    border-blue-200
                  "
                >

                  <div>

                    <p
                      className="
                        text-sm
                        font-semibold
                        text-blue-900
                      "
                    >
                      {text.schoolStatus}
                    </p>

                    <p
                      className="
                        text-xs
                        text-blue-400
                        mt-0.5
                      "
                    >
                      {text.showOnWebsite}
                    </p>

                  </div>


                  <label
                    className="
                      relative
                      inline-flex
                      items-center
                      cursor-pointer
                      flex-shrink-0
                    "
                  >

                    <input
                      type="checkbox"
                      name="is_active"
                      checked={
                        formData.is_active
                      }
                      onChange={
                        handleInputChange
                      }
                      className="
                        sr-only
                        peer
                      "
                    />

                    <div
                      className="
                        relative
                        w-11
                        h-6
                        bg-blue-200
                        rounded-full
                        transition-colors
                        peer-checked:bg-blue-900
                        after:content-['']
                        after:absolute
                        after:top-[2px]
                        after:left-[2px]
                        after:w-5
                        after:h-5
                        after:bg-white
                        after:rounded-full
                        after:shadow-sm
                        after:transition-all
                        peer-checked:after:translate-x-full
                      "
                    />

                  </label>

                </div>

              </div>

            </div>

          </div>


          <div
            className="
              mt-7
              pt-5
              border-t
              border-blue-200
              flex
              flex-col-reverse
              sm:flex-row
              sm:items-center
              sm:justify-end
              gap-3
            "
          >

            <button
              type="button"
              onClick={
                closeModal
              }
              disabled={
                submitting
              }
              className="
                h-11
                px-5
                rounded-xl
                border
                border-blue-200
                bg-white
                text-blue-500
                text-sm
                font-semibold
                hover:bg-blue-50
                disabled:opacity-50
                disabled:cursor-not-allowed
                transition-all
                duration-200
              "
            >
              {text.cancel}
            </button>


            <button
              type="submit"
              disabled={
                submitting
              }
              className="
                h-11
                inline-flex
                items-center
                justify-center
                gap-2
                px-6
                rounded-xl
                bg-red-600
                hover:bg-red-700
                text-white
                text-sm
                font-semibold
                shadow-sm
                hover:shadow-md
                disabled:opacity-60
                disabled:cursor-not-allowed
                transition-all
                duration-200
              "
            >

              {
                submitting ? (

                  text.saving

                ) : editingSchool ? (

                  <>

                    <FiEdit2
                      size={16}
                    />

                    {text.updateSchool}

                  </>

                ) : (

                  <>

                    <FiPlus
                      size={17}
                    />

                    {text.createSchool}

                  </>

                )
              }

            </button>

          </div>

        </form>

      </AdminModal>

    </div>

  );

};


export default AdminSchools;
